import pytorch_lightning as pl
from data import SymptomHierDataModule
from modelTestSymptom import HierClassifier 
from transformers import AutoTokenizer
from sklearn.metrics import f1_score

# 获取恢复了权重和超参数等的模型
model = HierClassifier.load_from_checkpoint(checkpoint_path='/E22301339/HAN-BERT/eRisk2018/lightning_logs/version_1/checkpoints/epoch=1-step=443.ckpt')
# 修改测试时需要的参数，例如预测的步数等
model.pred_step = 100
# 定义trainer
trainer = pl.Trainer(gpus=1, precision=16)
# 测试，自动调用test_step(), 其中dm为数据集 =-09-=3
tokenizer = AutoTokenizer.from_pretrained("/E22301339/bert-base-uncased")
data_module = SymptomHierDataModule(4, "/E22301339/HAN-BERT/eRisk2018/processed/combined_maxsim32_gpt", tokenizer, 128)
result=trainer.test(model=model, datamodule=data_module,verbose='true')
print(result)








